import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.DnrXFDHb.js";const i="/images/screenshots/api-key-list.png",s="/images/screenshots/api-key-create.png",u=JSON.parse('{"title":"创建 API Key","description":"在 CCWS 控制台创建 API Key（一串 sk- 开头的密码），用于让 ChatGPT（Codex）连接 CCWS。零基础用户跟着做即可。","frontmatter":{"title":"创建 API Key","description":"在 CCWS 控制台创建 API Key（一串 sk- 开头的密码），用于让 ChatGPT（Codex）连接 CCWS。零基础用户跟着做即可。"},"headers":[],"relativePath":"guide/api-key.md","filePath":"guide/api-key.md","lastUpdated":1783061751000}'),l={name:"guide/api-key.md"};function n(c,e,p,h,d,g){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="创建-api-key" tabindex="-1">创建 API Key <a class="header-anchor" href="#创建-api-key" aria-label="Permalink to &quot;创建 API Key&quot;">​</a></h1><p>这一页只做一件事：<strong>在 CCWS 控制台生成一串 API Key</strong>（读作&quot;A-P-I-Key&quot;）。</p><h3 id="为什么要创建它" tabindex="-1">为什么要创建它 <a class="header-anchor" href="#为什么要创建它" aria-label="Permalink to &quot;为什么要创建它&quot;">​</a></h3><p>API Key 就是 ChatGPT 连接 CCWS 服务的<strong>钥匙</strong>：</p><ul><li><strong>它是什么</strong>：一串以 <code>sk-</code> 开头的密码，用来证明&quot;这个账号有权限用 CCWS 的服务&quot;。</li><li><strong>用在哪里</strong>：配置的时候，要把它填进 CC Switch（就填一次，之后不用管）。</li><li><strong>没有它会怎样</strong>：ChatGPT 没有这把钥匙，就调不动 CCWS 的服务，配置了也白配。</li></ul><p>拿到这串 Key，配置的时候就要用到它。</p><h2 id="开始前-先确认充过值" tabindex="-1">开始前：先确认充过值 <a class="header-anchor" href="#开始前-先确认充过值" aria-label="Permalink to &quot;开始前：先确认充过值&quot;">​</a></h2><p>创建 Key 之前，确认你已经<strong>注册并充值</strong>：</p><ul><li>还没注册？→ <a href="/guide/register">注册 CCWS 账号</a></li><li>还没充值？→ <a href="/guide/recharge">给账号充值</a></li></ul><h2 id="登录-ccws-控制台" tabindex="-1">登录 CCWS 控制台 <a class="header-anchor" href="#登录-ccws-控制台" aria-label="Permalink to &quot;登录 CCWS 控制台&quot;">​</a></h2><p>用浏览器打开 CCWS 官网并登录：</p><p>👉 <a href="https://www.ccws.pro/" target="_blank" rel="noreferrer">https://www.ccws.pro/</a></p><p>登录后进的是<strong>控制台</strong>（管理账号的网页后台），左边能看到「API Key」「钱包」这些菜单。</p><h2 id="进-api-key-页面" tabindex="-1">进 API Key 页面 <a class="header-anchor" href="#进-api-key-页面" aria-label="Permalink to &quot;进 API Key 页面&quot;">​</a></h2><p>在控制台左边找到 <strong>「API Key」</strong> 或 <strong>「密钥管理」</strong>，点进去。</p><p><img src="'+i+'" alt="API 密钥页面" loading="lazy"></p><h2 id="创建并复制-key" tabindex="-1">创建并复制 Key <a class="header-anchor" href="#创建并复制-key" aria-label="Permalink to &quot;创建并复制 Key&quot;">​</a></h2><ol><li>点页面上的 <strong>「创建 Key」</strong>。</li><li>创建成功后，页面上会出现一串以 <code>sk-</code> 开头的字符，这就是你的 API Key。</li><li>点 <strong>「复制」</strong>，把这串 Key 复制下来，先粘到记事本里放着。</li></ol><p><img src="'+s+'" alt="创建 API 密钥" loading="lazy"></p><div class="tip custom-block"><p class="custom-block-title">✅ 完成标志</p><p>看到并复制到一串以 <code>sk-</code> 开头的 Key，这一步就完成了。以后任何工具要用 CCWS，填的都是这一串。</p></div><div class="warning custom-block"><p class="custom-block-title">⚠️ 安全提醒</p><p>API Key 就是你的密码：</p><ul><li>别发到聊天窗口、截图、群聊、文章里。</li><li>别提交到 GitHub（代码托管网站）这类公开仓库。</li><li>怀疑泄露了，回控制台删掉旧的、重新生成一串。</li></ul></div><h2 id="下一步-配置-chatgpt" tabindex="-1">下一步：配置 ChatGPT <a class="header-anchor" href="#下一步-配置-chatgpt" aria-label="Permalink to &quot;下一步：配置 ChatGPT&quot;">​</a></h2><p>Key 到手了，接下来是最后一步：</p><p><strong>👉 <a href="/guide/connect">配置 ChatGPT 连接 CCWS</a></strong> ——把请求地址和这串 Key 填进 ChatGPT，发一条测试消息，确认配置完成。</p><blockquote><p>顺便记住：CCWS 的请求地址是固定的，不用查、不用找，配置时直接填 <code>https://www.ccws.pro/v1</code> 就行。</p></blockquote>',25)])])}const y=a(l,[["render",n]]);export{u as __pageData,y as default};
